materials/Steel_Machined/Steel_Machined..inline_mdl:
mdl 1.4;

// OmniPBR adapter: NVIDIA Base steel albedo/ORM and vMaterials 4K milling normal.
// Texture sources and NVIDIA notices are pinned in benchmark/extra_visuals.json.
using ::OmniPBR import OmniPBR;
import ::tex::gamma_mode;

export material Steel_Machined(*) = OmniPBR(
    diffuse_texture: texture_2d("./textures/Steel_Stainless_BaseColor.png", ::tex::gamma_srgb),
    enable_ORM_texture: true,
    ORM_texture: texture_2d("./textures/Steel_Stainless_ORM.png", ::tex::gamma_linear),
    metallic_texture_influence: 1.0,
    reflection_roughness_texture_influence: 1.0,
    normalmap_texture: texture_2d("textures/stainless_milled_norm.jpg", ::tex::gamma_linear),
    bump_factor: 0.18);

materials/White_Glaze/White_Glaze.mdl.inline_mdl:
mdl 1.4;

// Engineering white ceramic glaze, not a measured or scanned hardware material.
// Reuses NVIDIA's 4K subtle glossy-coating normal without changing contact geometry.
using ::OmniPBR import OmniPBR;
import ::tex::gamma_mode;

export material White_Glaze(*) = OmniPBR(
    diffuse_color_constant: color(0.86, 0.84, 0.79),
    metallic_constant: 0.0,
    metallic_texture_influence: 0.0,
    reflection_roughness_constant: 0.18,
    specular_level: 0.5,
    normalmap_texture: texture_2d("../MetalPainted_White_Glossy_A/textures/T_MetalPainted_White_Glossy_A_Normal.png", ::tex::gamma_linear),
    bump_factor: 0.35);
